const rand = (n, seed) => {
  // simple LCG for reproducibility
  let s = seed
  const pts = []
  for (let i = 0; i < n; i++) {
    s = (s * 1103515245 + 12345) % 2147483648
    const x = (s % 1000) / 100
    s = (s * 1103515245 + 12345) % 2147483648
    const y = (s % 1000) / 100
    pts.push([x, y])
  }
  pts.push([...pts[0]])
  return [pts]
}

const area = (mp) => {
  let a = 0
  for (const poly of mp) {
    for (let r = 0; r < poly.length; r++) {
      const ring = poly[r]
      let ra = 0
      for (let i = 0; i < ring.length - 1; i++) {
