import pc from "../src/index"

const rand = (n, seed) => {
  let s = seed
  const pts = []
  for (let i = 0; i < n; i++) {
    s = (s * 1103515245 + 12345) % 2147483648
    const x = (s % 1000) / 100
    s = (s * 1103515245 + 12345) % 2147483648
    const y = (s % 1000) / 100
    pts.push([x, y])
  }
  pts.push([...pts[0]])
  return [pts]
}

// winding number of point in ring
const winding = (ring, px, py) => {
  let w = 0
  for (let i = 0; i < ring.length - 1; i++) {
    const [x1, y1] = ring[i]
    const [x2, y2] = ring[i+1]
    if (y1 <= py) {
      if (y2 > py && (x2-x1)*(py-y1) - (px-x1)*(y2-y1) > 0) w++
    } else {
      if (y2 <= py && (x2-x1)*(py-y1) - (px-x1)*(y2-y1) < 0) w--
    }
  }
  return w
}

// point in multipolygon (even-odd per ring with hole handling via winding too)
const inResult = (mp, px, py) => {
  for (const poly of mp) {
    let w = 0
    for (const ring of poly) w += winding([...ring], px, py)
    if (w !== 0) return true
  }
  return false
}

test("fuzz2 union vs nonzero fill", () => {
  let mismatches = 0
  const bad = []
  for (let seed = 1; seed <= 200; seed++) {
    const geom = rand(7, seed)
    let out
    try { out = pc.union(geom) } catch (e) { bad.push([seed, "THROW"]); continue }
    let bad2 = 0
    for (let gx = 5; gx < 1000; gx += 37) {
      for (let gy = 5; gy < 1000; gy += 37) {
        const px = gx / 100 + 0.013, py = gy / 100 + 0.007
        const expect = winding(geom[0], px, py) !== 0
        const got = inResult(out, px, py)
        if (expect !== got) bad2++
      }
    }
    if (bad2 > 0) { mismatches++; if (bad.length < 10) bad.push([seed, bad2]) }
  }
  console.log("mismatched polys:", mismatches, "examples:", JSON.stringify(bad))
})
