  let w = 0
  for (let i = 0; i < ring.length - 1; i++) {
    const [x1, y1] = ring[i]
    const [x2, y2] = ring[i+1]
    if (y1 <= py) {
      if (y2 > py && (x2-x1)*(py-y1) - (px-x1)*(y2-y1) > 0) w++
    } else {
      if (y2 <= py && (x2-x1)*(py-y1) - (px-x1)*(y2-y1) < 0) w--
    }
  }
  return w
}

const inGeom = (geom, px, py) => {
  // geom: Polygon (array of rings) using nonzero rule across all rings
  let w = 0
  for (const ring of geom) w += winding(ring, px, py)
  return w !== 0
}

const inMP = (mp, px, py) => mp.some((poly) => inGeom(poly, px, py))

