  const stats = { intersection: 0, difference: 0, xor: 0, union: 0 }
  const bad = { intersection: [], difference: [], xor: [], union: [] }
  for (let seed = 1; seed <= 150; seed++) {
    const geom = rand(7, seed)
    const results = {}
    for (const op of ["union", "intersection", "difference", "xor"]) {
      try {
        results[op] = op === "union" ? pc.union(geom) : pc[op](geom, rect)
      } catch (e) {
        bad[op].push([seed, "THROW: " + e.message.slice(0, 60)])
        stats[op]++
        continue
      }
    }
    for (let gx = 5; gx < 1000; gx += 31) {
      for (let gy = 5; gy < 1000; gy += 29) {
        const px = gx / 100 + 0.013, py = gy / 100 + 0.007
        const inG = inGeom(geom, px, py)
        const inR = inGeom(rect, px, py)
