          intersection: inG && inR,
          difference: inG && !inR,
          xor: inG !== inR,
        }
        for (const op of Object.keys(expects)) {
          if (!results[op]) continue
          if (inMP(results[op], px, py) !== expects[op]) {
            stats[op]++
            if (bad[op].length < 5) bad[op].push([seed, px, py])
          }
        }
      }
    }
  }
