import pc from "../src/index"

// random walk on integer grid -> many colinear self-overlaps & self-touches
const walk = (n, seed) => {
  let s = seed
  const next = () => { s = (s * 1103515245 + 12345) % 2147483648; return s }
  let x = 5, y = 5
  const pts = [[x, y]]
  for (let i = 0; i < n; i++) {
    const d = next() % 4
    const len = (next() % 4) + 1
    if (d === 0) x += len
    else if (d === 1) x -= len
    else if (d === 2) y += len
    else y -= len
    x = Math.max(0, Math.min(10, x))
    y = Math.max(0, Math.min(10, y))
    pts.push([x, y])
  }
  pts.push([...pts[0]])
  return [pts]
}

const winding = (ring, px, py) => {
  let w = 0
  for (let i = 0; i < ring.length - 1; i++) {
    const [x1, y1] = ring[i]
    const [x2, y2] = ring[i+1]
    if (y1 <= py) {
      if (y2 > py && (x2-x1)*(py-y1) - (px-x1)*(y2-y1) > 0) w++
    } else {
      if (y2 <= py && (x2-x1)*(py-y1) - (px-x1)*(y2-y1) < 0) w--
    }
  }
  return w
}
const inMP = (mp, px, py) => mp.some((poly) => {
  let w = 0
  for (const ring of poly) w += winding(ring, px, py)
  return w !== 0
})

test("fuzz4 grid walks", () => {
  let bad = 0, throws = 0
  const examples = []
  for (let seed = 1; seed <= 500; seed++) {
    const geom = walk(12, seed)
    let out
    try { out = pc.union(geom) } catch (e) {
      throws++
      if (examples.length < 5) examples.push([seed, "THROW: " + e.message.slice(0, 70)])
      continue
    }
    for (let gx = 0; gx <= 40; gx++) {
      for (let gy = 0; gy <= 40; gy++) {
        const px = gx / 4 + 0.031, py = gy / 4 + 0.017
        const expect = winding(geom[0], px, py) !== 0
        if (inMP(out, px, py) !== expect) {
          bad++
          if (examples.length < 5) examples.push([seed, px, py, expect])
        }
      }
    }
  }
  console.log("bad:", bad, "throws:", throws, "examples:", JSON.stringify(examples))
})
