})

describe("self-touching & degenerate rings", () => {
  test("union of ring touching itself at a point", () => {
    const touchPoint = [
      [[0, 0], [2, 0], [2, 2], [0, 2], [0, 0], [2, 2], [4, 2], [4, 4], [2, 4], [2, 2]],
